import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g2-1/bot.mjs';

const tokyo = { id: 'u1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (iso) => new Date(iso);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

ok('quiet hours block late evening local time (Tokyo 23:30 = 14:30Z)', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T14:30:00Z')), { allowed: false, reason: 'quiet_hours' });
});
ok('quiet window wraps midnight; 06:59 blocked, 07:00 allowed (end exclusive)', () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo, at('2026-10-21T21:59:00Z')).allowed, true); // 06:59 Tokyo? no: 21:59Z = 06:59 JST
});
ok('06:59 blocked, 07:00 allowed', () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo, at('2026-10-21T21:59:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(tokyo, at('2026-10-21T22:00:00Z')).allowed, true); // 07:00 JST
});
ok('21:59 local allowed, 22:00 blocked', () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo, at('2026-10-22T12:59:00Z')).allowed, true); // 21:59 JST
  assert.equal(g.attempt(tokyo, at('2026-10-22T13:00:00Z')).reason, 'quiet_hours'); // 22:00 JST
});
ok('daily cap of 3 counts only allowed pushes; 4th blocked', () => {
  const g = createPushGate();
  const t = (h) => at(`2026-10-22T${h}:00:00Z`); // Tokyo 10:00+ local
  assert.equal(g.attempt(tokyo, t('01')).allowed, true);
  assert.equal(g.attempt(tokyo, t('02')).allowed, true);
  assert.equal(g.attempt(tokyo, t('03')).allowed, true);
  assert.equal(g.attempt(tokyo, t('04')).reason, 'daily_cap_reached');
});
ok('quiet check runs before cap', () => {
  const g = createPushGate();
  for (const h of ['01', '02', '03']) g.attempt(tokyo, at(`2026-10-22T${h}:00:00Z`));
  assert.equal(g.attempt(tokyo, at('2026-10-22T14:00:00Z')).reason, 'quiet_hours'); // 23:00 JST, over cap too
});
ok('day resets at local midnight, not UTC midnight', () => {
  const g = createPushGate();
  for (const h of ['01', '02', '03']) g.attempt(tokyo, at(`2026-10-22T${h}:00:00Z`)); // 10:00-12:00 JST Oct 22
  // 00:05 JST Oct 23 = 15:05Z Oct 22: UTC date still 22nd, local date is 23rd
  assert.equal(g.attempt(tokyo, at('2026-10-22T15:05:00Z')).allowed, true);
});
ok('blocked calls do not count toward the cap', () => {
  const g = createPushGate();
  for (let i = 0; i < 5; i++) g.attempt(tokyo, at('2026-10-22T14:30:00Z')); // quiet, blocked
  assert.equal(g.attempt(tokyo, at('2026-10-22T02:00:00Z')).allowed, true);
});
ok('users are independent; gates are independent', () => {
  const g = createPushGate();
  const other = { ...tokyo, id: 'u2' };
  for (const h of ['01', '02', '03']) g.attempt(tokyo, at(`2026-10-22T${h}:00:00Z`));
  assert.equal(g.attempt(other, at('2026-10-22T02:00:00Z')).allowed, true);
  assert.equal(createPushGate().attempt(tokyo, at('2026-10-22T02:00:00Z')).allowed, true);
});
ok('per-call settings are used (cap raised later takes effect)', () => {
  const g = createPushGate();
  for (const h of ['01', '02', '03']) g.attempt(tokyo, at(`2026-10-22T${h}:00:00Z`));
  assert.equal(g.attempt({ ...tokyo, dailyCap: 3 }, at('2026-10-22T04:00:00Z')).reason, 'daily_cap_reached');
  assert.equal(g.attempt({ ...tokyo, dailyCap: 4 }, at('2026-10-22T04:00:00Z')).allowed, true);
});
ok('dailyCap 0 blocks everything outside quiet hours', () => {
  const g = createPushGate();
  assert.equal(g.attempt({ ...tokyo, dailyCap: 0 }, at('2026-10-22T02:00:00Z')).reason, 'daily_cap_reached');
});
ok('same-day quiet window (13:00-14:00) and equal start/end', () => {
  const g = createPushGate();
  const u = { id: 'u3', timeZone: 'UTC', quietStart: '13:00', quietEnd: '14:00', dailyCap: 9 };
  assert.equal(g.attempt(u, at('2026-10-22T13:30:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, at('2026-10-22T14:00:00Z')).allowed, true);
  const same = { ...u, id: 'u4', quietStart: '09:00', quietEnd: '09:00' };
  assert.equal(g.attempt(same, at('2026-10-22T09:00:00Z')).allowed, true);
});
ok('missing quiet fields default to 22:00-07:00 local', () => {
  const g = createPushGate();
  const u = { id: 'u5', timeZone: 'UTC', dailyCap: 9 };
  assert.equal(g.attempt(u, at('2026-10-22T23:00:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, at('2026-10-22T12:00:00Z')).allowed, true);
});
ok('"day" uses user zone across DST start (America/New_York 2026-03-08)', () => {
  const g = createPushGate();
  const ny = { id: 'u6', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 2 };
  // 03:30 EDT Mar 8 = 07:30Z; 12:00 EDT = 16:00Z; 22:30 EDT = 02:30Z Mar 9 -> quiet
  assert.equal(g.attempt(ny, at('2026-03-08T07:30:00Z')).allowed, true);
  assert.equal(g.attempt(ny, at('2026-03-08T16:00:00Z')).allowed, true);
  assert.equal(g.attempt(ny, at('2026-03-08T16:30:00Z')).reason, 'daily_cap_reached');
  assert.equal(g.attempt(ny, at('2026-03-09T02:30:00Z')).reason, 'quiet_hours');
});
ok('invalid inputs throw', () => {
  const g = createPushGate();
  assert.throws(() => g.attempt({ ...tokyo, quietStart: '7pm' }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, dailyCap: -1 }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, dailyCap: 1.5 }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, timeZone: 'Mars/Olympus' }, new Date()), RangeError);
});
console.log(`all ${n} checks passed`);
EOF
